package main

import (
	"bytes"
	"context"
	"encoding/json"
	"regexp"
	"strings"
	"sync"
	"time"
	"unicode/utf8"
)

const journalPreviewLimit = 64 << 10

// MCPCall is captured at the client/protocol boundary, never generated by the LLM.
type MCPCall struct {
	Sequence          int    `json:"sequence"`
	Server            string `json:"server"`
	Tool              string `json:"tool"`
	StartedAt         string `json:"startedAt"`
	DurationMS        int64  `json:"durationMs"`
	Arguments         any    `json:"arguments"`
	Result            any    `json:"result"`
	Error             string `json:"error,omitempty"`
	Truncated         bool   `json:"truncated,omitempty"`
	OmittedNestedLogs bool   `json:"omittedNestedLogs,omitempty"`
}

type journalContextKey struct{}

// A recorder belongs to one question. Shared MCP connections carry no mutable journal.
type MCPJournal struct {
	mu      sync.Mutex
	calls   []MCPCall
	secrets []string
}

func withJournal(ctx context.Context, secrets []string) (context.Context, *MCPJournal) {
	j := &MCPJournal{calls: []MCPCall{}, secrets: append([]string(nil), secrets...)}
	return context.WithValue(ctx, journalContextKey{}, j), j
}

func journalFrom(ctx context.Context) *MCPJournal {
	j, _ := ctx.Value(journalContextKey{}).(*MCPJournal)
	return j
}

func (j *MCPJournal) snapshot() []MCPCall {
	j.mu.Lock()
	defer j.mu.Unlock()
	return append([]MCPCall{}, j.calls...)
}

func (j *MCPJournal) add(call MCPCall, start time.Time, args, result any, err error) {
	call.DurationMS = time.Since(start).Milliseconds()
	call.Arguments, call.Truncated, call.OmittedNestedLogs = j.prepare(args)
	value, truncated, omitted := j.prepare(result)
	call.Result = value
	call.Truncated = call.Truncated || truncated
	call.OmittedNestedLogs = call.OmittedNestedLogs || omitted
	if err != nil {
		call.Error = j.redactText(err.Error())
	}
	j.mu.Lock()
	defer j.mu.Unlock()
	call.Sequence = len(j.calls) + 1
	j.calls = append(j.calls, call)
}

var bearerPattern = regexp.MustCompile(`(?i)Bearer\s+[A-Za-z0-9._~+/=-]{8,}`)

func (j *MCPJournal) redactText(s string) string {
	for _, secret := range j.secrets {
		if len(secret) >= 8 {
			s = strings.ReplaceAll(s, secret, "[скрыто]")
		}
	}
	return bearerPattern.ReplaceAllString(s, "Bearer [скрыто]")
}

func secretField(key string) bool {
	k := strings.ToLower(strings.NewReplacer("_", "", "-", "", " ", "").Replace(key))
	switch k {
	case "key", "apikey", "deepseekapikey", "githubtoken", "token", "accesstoken", "refreshtoken", "authorization", "password", "secret", "supportaccesstoken", "projectmcptoken", "supportmcptoken":
		return true
	}
	return false
}

func (j *MCPJournal) sanitize(v any, omitted *bool) any {
	switch value := v.(type) {
	case map[string]any:
		out := make(map[string]any, len(value))
		for key, child := range value {
			if strings.EqualFold(key, "mcpCalls") {
				out[key] = "[вложенный журнал не включён]"
				*omitted = true
			} else if secretField(key) {
				out[key] = "[скрыто]"
			} else {
				out[key] = j.sanitize(child, omitted)
			}
		}
		return out
	case []any:
		out := make([]any, len(value))
		for i, child := range value {
			out[i] = j.sanitize(child, omitted)
		}
		return out
	case string:
		return j.redactText(value)
	default:
		return v
	}
}

func (j *MCPJournal) prepare(v any) (any, bool, bool) {
	data, err := json.Marshal(v)
	if err != nil {
		return "[результат нельзя представить как JSON]", false, false
	}
	var value any
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.UseNumber()
	if decoder.Decode(&value) != nil {
		return "[некорректный JSON]", false, false
	}
	omitted := false
	value = j.sanitize(value, &omitted)
	data, _ = json.Marshal(value)
	if len(data) > journalPreviewLimit {
		preview := data[:journalPreviewLimit]
		for !utf8.Valid(preview) {
			preview = preview[:len(preview)-1]
		}
		return map[string]any{"preview": string(preview), "originalBytes": len(data), "truncated": true}, true, omitted
	}
	return value, false, omitted
}
